  "about_items": [
    {
      "n": "#30·14",
      "text": "This beige top features a soft, slip-style neckline with delicate spaghetti straps and a fitted waist that accentuates your figure. Its smooth fabric drapes elegantly over the hips, creating a clean line from shoulder to hip."
    },
    {
      "n": "#77·08",
      "text": "These wide-leg trousers are crafted from lightweight linen in a light beige shade, offering effortless comfort with a relaxed yet structured fit. The elastic waistband and drawstring allow for easy movement while maintaining a polished silhouette."
    },
    {
      "n": "#369·11",
      "text": "These pink loafers are made from soft suede with a low-profile sole and a decorative bow across the vamp, adding a romantic touch to any outfit. Their sleek design ensures they stay stylish yet understated for everyday wear."
    },
    {
      "n": "#277·16",
      "text": "This pink headband is embellished with shimmering pearls and sparkling crystals, set against a velvet base that catches the light beautifully. Its curved shape sits comfortably atop your head, adding just the right amount of glamour to complete your ensemble."
    },
    {
      "n": "#123·35",
      "text": "This mini bag features a textured surface in a warm peach tone, complemented by a slender strap that can be worn across the body or on the shoulder. Its compact size makes it ideal for carrying essentials during an outing."
    }
  ]
